import { Foundation } from "class-base-static";

export class Formatter extends Foundation {
  derivedField = "derived-field";

  constructor(prefix) {
    super(prefix);
    console.log("derived-constructor");
  }

  render(value) {
    return `derived(${super.render(value)}:${this.derivedField})`;
  }

  static create(prefix) {
    return new Formatter(prefix);
  }
}
